function readConfig(){try{const saved=JSON.parse(localStorage.getItem(CONFIG_KEY)||'null');if(saved&&Array.isArray(saved.config?.types)&&saved.config.types.length&&Array.isArray(saved.config?.libraries)&&saved.config.libraries.length){CONFIG.types=saved.config.types;CONFIG.libraries=saved.config.libraries.map(l=>({...l,key:l.key||l.name}));configJournal=saved.journal||[]}}catch{}}
