function applyConfigOps(data){data.configOps=data.configOps||[];for(const op of configJournal){if(data.configOps.includes(op.id))continue;for(const a of data.assets){if(op.scope==='library'&&a.kind===op.old)a.kind=op.name;if(op.scope==='category'&&a.kind===op.library&&a.category===op.old)a.category=op.name;if(op.scope==='tag'&&a.kind===op.library)a.tags=a.tags.map(t=>t===op.old?op.name:t)}data.configOps.push(op.id)}return data}

