 ['a1','清透底妆 · 出镜人物','人物','电商出镜',['女性','自然妆','清新'],'woman'],['a2','日常通勤 · 人物形象','人物','电商出镜',['女性','职场'],'woman2'],['a3','都市短剧 · 男主形象','人物','微短剧角色',['男性','成熟'],'man'],['a4','轻熟通勤 · 整套造型','服装','职场造型',['通勤','简约','黑色'],'outfit'],['a5','白色连衣裙 · 日常造型','服装','日常穿搭',['白色','简约'],'dress'],['a6','暖光客厅 · 居家日常','场景','居家空间',['室内','自然光','暖色'],'room'],['a7','开放办公区 · 职场剧情','场景','商业空间',['室内','明亮','极简'],'studio'],['a8','护肤套组 · 产品陈列','道具','美妆产品',['护肤','日常'],'beauty'],['a9','护肤瓶 · 产品参考','道具','美妆产品',['护肤','玻璃'],'bottle'],['a10','通勤手袋 · 角色配饰','道具','配饰',['日常','金属'],'bag'],['a11','LUMIÈRE · 演示品牌标识','品牌LOGO','品牌标识',['文字标','黑色','透明底'],'logo']
