let state={page:'projects',projectType:'all',category:'all',tags:[],filters:false,search:'',searchTab:'all',sort:'updated',project:null,role:'all',folder:'all',projectCategory:'all',asset:null,layer:null,flow:null,confirm:null};
let toastTimer,parseTimer;
const db=()=>stores[mode];const uid=()=>crypto.randomUUID();const now=()=>new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'}).slice(0,16);
function persist(){try{localStorage.setItem('xingce-assets-v1-'+mode,JSON.stringify(db()))}catch{toast('浏览器空间不足，当前更改只保留在本次页面中')}}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3200)}
function allRefs(a){return db().projects.flatMap(p=>p.refs.filter(r=>r.asset===a).map(r=>({p,r})));}
function countRefs(a){return allRefs(a).length}function getAsset(id){return db().assets.find(a=>a.id===id)}function getProject(){return db().projects.find(p=>p.id===state.project)}
function assetMatches(a,q){const hay=[a.name,a.kind,a.category,...a.tags,a.description].join(' ').toLowerCase();q=q.trim().toLowerCase();if(hay.includes(q))return true;const aliases={'女生':'女性','女孩':'女性','女人':'女性','男生':'男性','男人':'男性','办公室':'办公','口红':'彩妆','裙子':'裙','化妆品':'美妆','面霜':'护肤','logo':'品牌LOGO'};let terms=[...new Set([...CONFIG.libraries.flatMap(l=>[l.name,...l.categories,...l.tags]),'客厅','办公','裙','底妆','出镜','手袋',...Object.keys(aliases)].filter(t=>q.includes(t.toLowerCase())).map(t=>aliases[t]||t))];return terms.length>0&&terms.some(t=>hay.includes(t.toLowerCase()))}
function projectMatches(p,q){return [p.name,type(p.type).name,p.note,...p.roles.map(r=>r.name)].join(' ').toLowerCase().includes(q.toLowerCase())}
function assetSearch(){return `<form class="global-search asset-search" id="global-search">${icon('search')}<input id="global-query" aria-label="搜索全部项目和资产" placeholder="搜索全部项目和资产" value="${esc(state.search)}">${state.search?'<button type="button" class="search-clear" data-action="clear-search" aria-label="清空搜索">×</button>':''}<button type="submit" class="search-submit" aria-label="搜索">${icon('search')}</button></form>`;}
function header(){document.querySelector('#header').innerHTML=`<div class="brand"><i class="brandmark"></i>星策云视频 <span class="internal">内网</span></div><nav>${['首页','成片','素材','脚本','商品','AI工具','AI资产','数据','更多'].map(n=>`<span class="${n==='AI资产'?'active':''}">${n}</span>`).join('')}</nav><span class="header-extra">${icon('bell')}</span><span class="header-extra">${icon('help')}</span><div class="user-menu"><button class="user-info ghost" data-action="user-menu" aria-expanded="false"><span class="avatar">汤</span>汤莉 <span class="menu-chevron">⌄</span></button><div class="user-dropdown" id="user-dropdown" hidden><a href="admin.html" target="_blank" rel="noopener">${icon('grid')}管理后台</a></div></div>`;}
function sidebar(){document.querySelector('#sidebar').innerHTML=`<div class="side-label">工作台</div><button class="side-item ${state.page==='projects'?'on':''}" data-action="page" data-value="projects">${icon('grid')}<span>项目总览</span></button><div class="side-label">图库</div>${CONFIG.libraries.map(l=>`<button class="side-item ${state.page===l.name?'on':''}" data-action="page" data-value="${l.name}">${icon(l.icon)}<span>${l.name==='品牌LOGO'||l.name.endsWith('图库')?l.name:l.name+'图库'}</span><small>${db().assets.filter(a=>a.kind===l.name).length}</small></button>`).join('')}<div class="side-footer"><div class="note">前端交互演示</div><div class="mode">${btn('mode','空数据',mode==='empty'?'on':'','empty')}${btn('mode','示例数据',mode==='demo'?'on':'','demo')}</div><div class="note">${mode==='demo'?'当前展示示例项目与资产':'默认空数据，可上传体验'}</div>${btn('reset','重置当前演示','ghost')}</div>`;}
function empty(title,desc,action,label){return `<div class="empty"><div class="empty-symbol">${icon('folder')}</div><h3>${title}</h3><p>${desc}</p>${action?btn(action,icon('plus')+label,'primary'):''}</div>`}
function cover(p){let imgs=[...new Set(p.refs.map(r=>r.asset))].map(getAsset).filter(Boolean).slice(0,3);if(!imgs.length)return `<div class="cover empty-cover">${icon('folder')}<span class="badge">${type(p.type).name}</span></div>`;while(imgs.length<3)imgs.push(imgs[0]);return `<div class="cover">${imgs.map(a=>`<img src="${esc(a.url)}" alt="${esc(a.name)}">`).join('')}<span class="badge">${type(p.type).name}</span></div>`}
function projectCard(p){return `<article class="project" tabindex="0" role="button" aria-label="打开项目 ${esc(p.name)}" data-action="project" data-value="${p.id}">${cover(p)}<div class="project-info"><div class="project-head"><h3>${esc(p.name)}</h3></div><div class="meta"><span class="person"><i class="mini-avatar">${esc(p.creator.slice(0,1))}</i>${esc(p.creator)}</span><span>${p.refs.length} 个资产</span></div><div class="meta"><span>创建 ${esc(p.created)}</span></div><div class="meta"><span>更新 ${esc(p.updated)}</span></div></div></article>`}
function assetCard(a,context=''){return `<article class="asset-card" tabindex="0" role="button" aria-label="查看资产 ${esc(a.name)}" data-kind="${esc(lib(a.kind)?.key||a.kind)}" data-action="asset" data-value="${a.id}" data-context="${esc(context)}"><div class="asset-image"><img src="${esc(a.url)}" alt="${esc(a.name)}" loading="lazy"></div><div class="asset-name">${esc(a.name)}</div><div class="asset-bottom"><span>${countRefs(a.id)} 次引用</span>${context==='project'?`<button class="ghost" style="padding:0;font-size:12px" data-action="remove-ref" data-value="${a.id}">移出项目</button>`:''}</div></article>`}
function projectsPage(){let ps=db().projects.filter(p=>state.projectType==='all'||p.type===state.projectType);ps.sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name,'zh-CN'):(b[state.sort]||'').localeCompare(a[state.sort]||''));return `<div class="breadcrumb">AI资产 / 工作台</div><div class="title-row"><div><h1>项目总览</h1><p>集中管理创作项目，让每一份资产有迹可循</p></div><div class="actions page-actions">${assetSearch()}${btn('new-project',icon('plus')+'新建项目')}${btn('import',icon('upload')+'导入项目','primary')}</div></div><div class="stats">${[['项目总数','folder',db().projects.length],[CONFIG.types.find(t=>t.id==='person')?.name||'人物项目','person',db().projects.filter(p=>p.type==='person').length],[CONFIG.types.find(t=>t.id==='script')?.name||'脚本项目','script',db().projects.filter(p=>p.type==='script').length]].map(([name,i,n])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><div><span>${name}</span><strong>${n}<span style="font-size:13px;font-weight:400;margin-left:8px">个</span></strong></div></div>`).join('')}</div><section class="panel"><div class="toolbar"><div class="tabs">${btn('ptype','全部项目 <small>'+db().projects.length+'</small>',state.projectType==='all'?'on':'','all')}${CONFIG.types.map(t=>btn('ptype',t.name,state.projectType===t.id?'on':'',t.id)).join('')}</div><select class="select-small" id="project-sort" aria-label="项目排序"><option value="updated" ${state.sort==='updated'?'selected':''}>最近更新</option><option value="created" ${state.sort==='created'?'selected':''}>最近创建</option><option value="name" ${state.sort==='name'?'selected':''}>项目名称</option></select></div>${ps.length?`<div class="projects">${ps.map(projectCard).join('')}</div><div class="section-foot">共 ${ps.length} 个项目 · 所有资产通过引用关联</div>`:empty('还没有项目','从新建项目开始，或导入画布中的图片资产','new-project','新建项目')}</section>`}
function gallery(){const l=lib(state.page);let as=db().assets.filter(a=>a.kind===l.name&&(state.category==='all'||a.category===state.category)&&(!state.tags.length||state.tags.some(t=>a.tags.includes(t))));return `<div class="breadcrumb">AI资产 / 图库 / ${l.name==='品牌LOGO'||l.name.endsWith('图库')?l.name:l.name+'图库'}</div><div class="title-row"><div><h1>${l.name==='品牌LOGO'||l.name.endsWith('图库')?l.name:l.name+'图库'}</h1><p>沉淀${l.name==='人物'?'角色形象':l.name==='服装'?'服装造型':l.name==='场景'?'场景空间':l.name==='道具'?'产品与道具':'品牌视觉'}，随时引用到你的创作项目</p></div><div class="actions page-actions">${assetSearch()}${btn('upload',icon('plus')+'上传图片','primary')}</div></div><section class="panel"><div class="toolbar"><div class="tabs">${btn('category','全部 <small>'+db().assets.filter(a=>a.kind===l.name).length+'</small>',state.category==='all'?'on':'','all')}${l.categories.map(c=>btn('category',c,state.category===c?'on':'',c)).join('')}</div>${btn('filters',icon('filter')+'筛选'+(state.tags.length?' · '+state.tags.length:''),state.filters?'chip on':'')}</div>${state.filters?`<div class="filters"><div class="toolbar" style="margin-bottom:12px"><span>标签 <small class="muted">多选 · 匹配任一标签</small></span>${btn('clear-filters','重置','ghost')}</div><div class="chips">${l.tags.map(t=>btn('tag',t,'chip '+(state.tags.includes(t)?'on':''),t)).join('')}</div><div class="note" style="margin-top:12px">演示分类与标签，由配置项提供</div></div>`:''}<div class="result-summary"><span class="count">共 ${as.length} 张资产</span>${state.tags.length?`<div class="active-filters">${state.tags.map(t=>btn('tag',esc(t)+' ×','chip on',t)).join('')}${btn('clear-filters','清空筛选','ghost')}</div>`:''}</div>${as.length?`<div class="asset-grid">${as.map(a=>assetCard(a)).join('')}</div><div class="section-foot">已显示全部资产</div>`:empty(db().assets.some(a=>a.kind===l.name)?'没有匹配的资产':'图库还是空的',db().assets.some(a=>a.kind===l.name)?'试试切换分类或重置标签筛选':'上传图片，解析后确认分类并保存到图库','upload','上传图片')}</section>`}
function searchPage(){const q=state.search.trim();let ps=q?db().projects.filter(p=>projectMatches(p,q)):[],as=q?db().assets.filter(a=>assetMatches(a,q)):[];return `<div class="breadcrumb">AI资产 / 搜索结果</div><div class="title-row"><div><h1>搜索结果</h1><p>“${esc(q)}” · 找到 ${ps.length} 个项目和 ${as.length} 张资产</p></div><div class="actions page-actions">${assetSearch()}${btn('page','返回项目总览','','projects')}</div></div><div class="tip">前端演示：当前根据名称、分类、标签与描述模拟匹配，未接入真实向量服务。</div><section class="panel"><div class="toolbar"><div class="tabs">${[['all','全部'],['projects','项目'],['assets','资产']].map(([id,n])=>btn('search-tab',n,state.searchTab===id?'on':'',id)).join('')}</div></div>${state.searchTab!=='assets'&&ps.length?`<h3 class="section-heading">项目 · ${ps.length}</h3><div class="projects" style="margin-bottom:30px">${ps.map(projectCard).join('')}</div>`:''}${state.searchTab!=='projects'&&as.length?`<h3 class="section-heading">资产 · ${as.length}</h3><div class="asset-grid">${as.map(a=>assetCard(a)).join('')}</div>`:''}${(!ps.length||state.searchTab==='assets')&&(!as.length||state.searchTab==='projects')?empty('没有找到匹配结果','试试“女性”“护肤”“职场”等词，或上传自己的资产'):''}</section>`}
function render(){for(const m of ['empty','demo'])applyConfigOps(stores[m]);header();sidebar();document.querySelector('#main').innerHTML=state.page==='projects'?projectsPage():state.page==='search'?searchPage():gallery();renderLayers()}
function modal(title,body,foot='',size='',front=false){return `<div class="overlay ${front?'front':''}" data-backdrop="${front?'front':'base'}"><section class="modal ${size}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2>${btn(front?'close-front':'close',icon('close'),'ghost')}</div>${body}${foot?`<div class="modal-foot">${foot}</div>`:''}</section></div>`}
function field(label,control){const id=control.match(/id="([^"]+)"/)?.[1];return `<div class="field"><label ${id?`for="${id}"`:''}>${label}</label>${control}</div>`}
function options(vals,selected,blank=''){return (blank?`<option value="">${blank}</option>`:'')+vals.map(v=>{let value=typeof v==='string'?v:v.id,name=typeof v==='string'?v:v.name;return `<option value="${esc(value)}" ${selected===value?'selected':''}>${esc(name)}</option>`}).join('')}
function projectModal(){const p=getProject();if(!p)return '';let as=p.refs.filter(r=>(state.role==='all'||r.role===state.role)&&(state.folder==='all'||r.folder===state.folder)).map(r=>getAsset(r.asset)).filter(Boolean);as=[...new Map(as.map(a=>[a.id,a])).values()].filter(a=>state.projectCategory==='all'||a.kind===state.projectCategory);let script=type(p.type).template==='roles';let folders=[...new Set(p.refs.map(r=>r.folder).filter(Boolean))];return modal(p.name,`<div class="modal-body project-detail"><div class="toolbar" style="margin-bottom:10px"><span class="tag">${type(p.type).name}</span><div class="project-tools">${btn('edit-project',icon('edit')+'编辑项目')}${btn('project-upload',icon('upload')+'导入图片')}${btn('pick-assets',icon('plus')+'引用图库资产')}${btn('delete-project',icon('trash'),'danger')}</div></div><div class="project-details-meta"><span>创建人 ${esc(p.creator)}</span><span>创建 ${esc(p.created)}</span><span>更新 ${esc(p.updated)}</span><span>${p.refs.length} 个资产引用</span></div>${script?`<div class="script-info"><div class="toolbar" style="margin-bottom:4px"><h3>脚本信息</h3>${btn('edit-script',icon('edit')+'编辑','ghost')}</div><div class="inline-label">脚本链接</div>${p.script?`<a href="${esc(safeLink(p.script))}" target="_blank" rel="noopener noreferrer">${esc(p.script)}</a>`:`<p style="font-size:13px">暂未填写脚本链接</p>`}<div class="inline-label" style="margin-top:10px">脚本备注</div><div style="font-size:13px;white-space:pre-wrap">${esc(p.note)||'暂未填写备注'}</div></div>`:''}${script?`<div class="role-layout"><div class="role-nav"><div class="note">角色</div>${btn('role','全部资产','ghost '+(state.role==='all'?'on':''),'all')}${p.roles.map(r=>btn('role',(r.avatar&&getAsset(r.avatar)?`<img src="${esc(getAsset(r.avatar).url)}" alt="" style="width:25px;height:25px;object-fit:cover;border-radius:50%">`:'')+esc(r.name),'ghost '+(state.role===r.id?'on':''),r.id)).join('')}${btn('new-role',icon('plus')+'新增角色','ghost')}</div><div>`:''}<div class="toolbar" style="margin-bottom:12px"><div class="tabs">${['all',...CONFIG.libraries.map(l=>l.name)].map(k=>btn('project-category',k==='all'?'全部':k,state.projectCategory===k?'on':'',k)).join('')}</div></div>${script&&state.role!=='all'?`<div class="role-description">${esc(p.roles.find(r=>r.id===state.role)?.description)} ${btn('edit-role',icon('edit'),'ghost',state.role)}${btn('delete-role',icon('trash'),'ghost danger',state.role)}</div>`:''}${folders.length?`<div class="folder-strip">${btn('folder','全部文件夹','chip '+(state.folder==='all'?'on':''),'all')}${folders.map(f=>btn('folder',icon('folder')+esc(f),'chip '+(state.folder===f?'on':''),f)).join('')}</div>`:''}${as.length?`<div class="asset-grid">${as.map(a=>assetCard(a,'project')).join('')}</div>`:empty('这里还没有资产','从图库引用，或导入新的图片','pick-assets','引用图库资产')}${script?'</div></div>':''}</div>`)}
function safeLink(s){try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
function assetModal(){const a=getAsset(state.asset);if(!a)return '';const l=lib(a.kind),refs=allRefs(a.id);return modal('资产详情',`<div class="detail-layout"><div class="detail-picture"><img src="${esc(a.url)}" alt="${esc(a.name)}">${btn('prev-asset',icon('back'),'prev')}${btn('next-asset',icon('chevron'),'next')}</div><div class="detail-fields"><span class="tag">${a.kind}</span><h2 style="margin:9px 0 20px">${esc(a.name)}</h2>${field('资产名称',`<input id="asset-name" value="${esc(a.name)}">`)}${field('二级分类',`<select id="asset-category">${options(l.categories,a.category)}</select>`)}<div class="field"><label>标签</label><div class="chips">${l.tags.map(t=>`<label class="chip ${a.tags.includes(t)?'on':''}" style="cursor:pointer"><input type="checkbox" name="asset-tag" value="${esc(t)}" ${a.tags.includes(t)?'checked':''}> ${t}</label>`).join('')}</div></div>${field('描述',`<textarea id="asset-description">${esc(a.description)}</textarea>`)}<div class="note">来源 ${esc(a.source)} · 创建 ${esc(a.created)}</div><div class="actions">${btn('save-asset','保存信息','primary')}${btn('download',icon('download')+'下载原图')}${btn('add-reference',icon('plus')+'添加到项目')}${btn('send-canvas',icon('canvas')+'发送到画布')}</div><h3 style="margin:23px 0 6px">引用记录 · ${refs.length}</h3>${refs.length?refs.map(({p,r})=>`<div class="ref-row"><span>${esc(p.name)}<small class="muted">${r.role?' · '+esc(p.roles.find(x=>x.id===r.role)?.name||''):''}</small></span>${btn('open-ref','查看','ghost',p.id)}</div>`).join(''):'<p style="font-size:13px">暂无引用</p>'}<div class="actions">${btn('delete-asset',icon('trash')+'删除资产','ghost danger')}</div></div></div>`,'','',true)}
function newProjectModal(edit=false){const p=edit?getProject():null;const t=p?.type||CONFIG.types[0].id;return modal(edit?'编辑项目':'新建项目',`<div class="modal-body">${field('项目名称 *',`<input id="new-name" maxlength="80" placeholder="为项目取一个名称" value="${esc(p?.name||'')}">`)}${field('项目类型',`<select id="new-type">${options(CONFIG.types,t)}</select>`)}<div id="new-script-fields" ${type(t).template!=='roles'?'hidden':''}>${field('脚本链接',`<input id="new-script" type="url" placeholder="粘贴脚本链接（选填）" value="${esc(p?.script||'')}">`)}${field('脚本备注',`<textarea id="new-note" placeholder="填写剧情简介、创作说明等">${esc(p?.note||'')}</textarea>`)}</div><div class="note">项目类型来自预设配置；创建人默认为当前演示用户汤莉。</div></div>`,btn('close-front','取消')+btn(edit?'save-project':'create-project',edit?'保存修改':'创建项目','primary'),'small',true)}
function editScript(){let p=getProject();return modal('编辑脚本信息',`<div class="modal-body">${field('脚本链接',`<input id="script-url" type="url" value="${esc(p.script)}" placeholder="https://">`)}${field('脚本备注',`<textarea id="script-note" style="min-height:160px">${esc(p.note)}</textarea>`)}</div>`,btn('close-front','取消')+btn('save-script','保存','primary'),'small',true)}
function roleModal(){const p=getProject(),r=p.roles.find(r=>r.id===state.layerValue);return modal(r?'编辑角色':'新增角色',`<div class="modal-body">${field('角色姓名 *',`<input id="role-name" value="${esc(r?.name||'')}" placeholder="例如：林悦 · 女主">`)}${field('角色说明',`<textarea id="role-description" placeholder="填写角色设定与造型要求">${esc(r?.description||'')}</textarea>`)}${field('角色头像',`<select id="role-avatar">${options(db().assets.filter(a=>a.kind===(CONFIG.libraries.find(l=>l.key==='人物')?.name||'人物')).map(a=>({id:a.id,name:a.name})),r?.avatar||'','暂不设置')}</select>`)}</div>`,btn('close-front','取消')+btn('save-role','保存角色','primary'),'small',true)}
function addReferenceModal(){const a=getAsset(state.asset),ps=db().projects;return modal('添加到项目',`<div class="modal-body"><p style="margin-bottom:18px">引用「${esc(a?.name)}」，不会复制或改动原始图片。</p>${ps.length?`${field('目标项目',`<select id="ref-project">${options(ps)}</select>`)}<div id="ref-role-container">${refRoleSelect(ps[0])}</div>`:empty('还没有项目','先创建项目，再引用资产')}</div>`,btn('back-to-asset','取消')+btn('save-reference','添加引用','primary'+(!ps.length?' disabled':'')),'small',true)}
function refRoleSelect(p){return p&&type(p.type).template==='roles'?field('所属角色',`<select id="ref-role">${options(p.roles,'','不指定角色')}</select>`):''}
function pickAssetsModal(){let p=getProject();return modal('引用图库资产',`<div class="modal-body"><div class="tip">勾选图库资产添加到项目；可以选择所属角色，原始资产保持不变。</div>${type(p.type).template==='roles'?field('所属角色',`<select id="pick-role">${options(p.roles,state.role==='all'?'':state.role,'不指定角色')}</select>`):''}<div class="upload-list">${db().assets.map(a=>`<label class="upload-pick"><input type="checkbox" name="pick-asset" value="${a.id}"><img src="${esc(a.url)}" alt="${esc(a.name)}"><span>${esc(a.name)}</span></label>`).join('')}</div>${!db().assets.length?empty('图库还是空的','先上传图片，再添加引用'):''}</div>`,btn('close-front','取消')+btn('save-picked','添加到项目','primary'),'medium',true)}
function sendCanvasModal(){return modal('发送到星策画布',`<div class="modal-body"><div class="tip">演示流程，不会写入真实画布。</div>${field('选择目标画布',`<select id="canvas-target"><option>清透底妆 · 电商创意画布</option><option>高光时刻 · 短剧分镜画布</option></select>`)}<p>将「${esc(getAsset(state.asset)?.name)}」添加到所选画布。</p></div>`,btn('back-to-asset','取消')+btn('finish-canvas','确认添加','primary'),'small',true)}
function renderLayers(){let html=state.project?projectModal():'';if(state.asset&&!['reference','canvas'].includes(state.layer))html+=assetModal();if(state.flow)html+=flowModal();else if(state.layer==='new'||state.layer==='edit-project')html+=newProjectModal(state.layer==='edit-project');else if(state.layer==='script')html+=editScript();else if(state.layer==='role')html+=roleModal();else if(state.layer==='reference')html+=addReferenceModal();else if(state.layer==='pick')html+=pickAssetsModal();else if(state.layer==='canvas')html+=sendCanvasModal();if(state.confirm)html+=modal(state.confirm.title,`<div class="modal-body"><div class="confirm-message">${esc(state.confirm.message)}</div></div>`,btn('cancel-confirm','取消')+btn('confirm-action','确认','primary'),'small',true);document.querySelector('#layers').innerHTML=html;if(typeof requestAnimationFrame==='function')requestAnimationFrame(enhanceDialogs);}
function startFlow(upload=false,target=null){state.asset=null;state.layer=null;state.flow={upload,target,step:0,source:'local',items:[],name:'',type:target?getProject().type:CONFIG.types[0].id,script:'',note:'',canvas:'c1',progress:0,folderRoles:{}};renderLayers()}
function flowModal(){let f=state.flow;const steps=['选择来源','选择图片','确认入库'];let body=`<div class="steps">${steps.map((s,i)=>`<span class="step ${f.step===i?'on':''}"><b>${i+1}</b>${s}</span>`).join('')}</div>`;let foot='';if(f.step===0){body+=`<div class="source-grid">${[['local','folder','本地导入','多张图片或整个文件夹'],['canvas','canvas','星策画布','选择画布，预览勾选图片'],['external','upload','外部画布','下载后上传图片或文件夹']].map(([id,i,t,d])=>btn('flow-source',icon(i)+`<strong>${t}</strong><small>${d}</small>`,'source-card '+(f.source===id?'on':''),id)).join('')}</div>${f.source==='external'?'<div class="tip" style="margin-top:18px">请先从外部画布下载图片，再上传图片或文件夹。本期不提供链接提取。</div>':''}${f.source==='canvas'?field('选择画布',`<select id="flow-canvas"><option value="c1" ${f.canvas==='c1'?'selected':''}>清透底妆 · 电商创意画布</option><option value="c2" ${f.canvas==='c2'?'selected':''}>高光时刻 · 短剧分镜画布</option></select>`):''}`;foot=btn('close-flow','取消')+btn('flow-next','下一步','primary');}
else if(f.step===1){if(f.source!=='canvas')body+=`<div class="drop" id="drop-zone">${icon('upload')}<h3>拖拽图片到这里，或选择文件上传</h3><p>支持 JPG、PNG、WebP、GIF、AVIF；保留文件夹结构</p><div class="actions" style="justify-content:center;margin-top:15px">${btn('choose-files','选择图片')}${btn('choose-folder','选择文件夹')}</div><input type="file" id="files-input" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" multiple hidden><input type="file" id="folder-input" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" webkitdirectory multiple hidden></div>`;else body+='<div class="tip">以下为星策画布的示例图片，勾选需要导入的内容。</div>';body+=`<div class="toolbar" style="margin:15px 0"><span>已选择 ${f.items.filter(i=>i.selected).length} / ${f.items.length} 张图片</span><div>${btn('flow-select-all','全选','ghost')}${btn('flow-select-none','取消全选','ghost')}</div></div><div class="upload-list">${f.items.map((i,n)=>`<label class="upload-pick"><input type="checkbox" data-flow-pick="${n}" ${i.selected?'checked':''}><img src="${esc(i.url)}" alt="${esc(i.name)}"><span>${esc(i.folder?i.folder+'/':'')}${esc(i.name)}</span></label>`).join('')}</div>`;foot=btn('flow-back','上一步')+btn('flow-parse','解析并继续','primary');}
else if(f.parsing){body+=`<div class="empty" style="padding:45px 20px"><div class="empty-symbol">${icon('logo')}</div><h3>正在模拟解析图片</h3><p>生成名称、分类与标签，保留原图，不进行裁切</p><div class="progress"><div style="width:${f.progress}%"></div></div><span>${f.progress}%</span></div>`;foot=btn('cancel-parse','取消解析');}
else if(f.done){body+=`<div class="empty" style="padding:40px 20px"><div class="empty-symbol success">${icon('check')}</div><h3>已完成入库</h3><p>${f.added} 张新资产，复用 ${f.reused} 张已有资产${f.target||!f.upload?'，已建立项目引用':''}</p></div>`;foot=btn('flow-finish',f.target||!f.upload?'查看项目':'查看图库','primary');}
else{if(!f.upload&&!f.target){body+=`<div class="cols">${field('项目名称 *',`<input id="flow-name" value="${esc(f.name)}" placeholder="请输入项目名称">`)}${field('项目类型',`<select id="flow-type">${options(CONFIG.types,f.type)}</select>`)}</div>${type(f.type).template==='roles'?`<div class="cols">${field('脚本链接',`<input id="flow-script" value="${esc(f.script)}" placeholder="脚本链接（选填）">`)}${field('脚本备注',`<textarea id="flow-note">${esc(f.note)}</textarea>`)}</div>`:''}`;}
body+=`<div class="tip">以下为模拟解析结果，请逐项确认。每张图片必须选择图库分类；标签仅可选择预设项。相同文件通过内容指纹复用。</div>${type(f.type).template==='roles'?`<div class="upload-summary"><h3>文件夹与角色</h3><p class="note">为文件夹填写角色姓名，留空则不指定角色。将保留原文件夹结构。</p>${[...new Set(f.items.filter(i=>i.selected).map(i=>i.folder).filter(Boolean))].map((folder,n)=>`<div class="cols" style="align-items:center;margin-top:9px"><span>${icon('folder')} ${esc(folder)}</span><input data-folder-role="${esc(folder)}" placeholder="角色姓名（选填）" value="${esc(f.folderRoles[folder]||'')}"></div>`).join('')||'<p class="note">当前图片没有文件夹，可在项目详情中新增角色后调整引用。</p>'}</div>`:''}`;
body+=f.items.filter(i=>i.selected).map(i=>{let n=f.items.indexOf(i),l=lib(i.kind);return `<div class="review-row"><img src="${esc(i.url)}" alt="${esc(i.name)}"><div><span class="note">资产名称</span><input data-review="name" data-index="${n}" value="${esc(i.name)}"><div class="note">${esc(i.folder||'未分组')}${db().assets.some(a=>a.fingerprint===i.fingerprint)?' · 将复用已有资产':''}</div>${type(f.type).template==='roles'?`<input aria-label="所属角色" data-review="roleName" data-index="${n}" value="${esc(i.roleName||'')}" placeholder="所属角色（选填）">`:''}</div><div><span class="note">图库分类 *</span><select data-review="kind" data-index="${n}">${options(CONFIG.libraries.map(l=>l.name),i.kind,'请手动选择图库')}</select><select aria-label="二级分类" data-review="category" data-index="${n}">${options(l?.categories||[],i.category,'选择二级分类')}</select></div><div><span class="note">标签</span><div class="chips">${(l?.tags||[]).map(t=>`<button data-review-tag="${esc(t)}" data-index="${n}" class="chip ${i.tags.includes(t)?'on':''}">${t}</button>`).join('')}</div></div></div>`}).join('');foot=btn('flow-back','上一步')+btn('flow-save','确认入库','primary');}
return modal(f.upload?'上传图片':f.target?'导入图片到项目':'导入项目',`<div class="modal-body">${body}</div>`,foot,'medium',true)}
function rememberFlow(){let f=state.flow;if(!f)return;for(const [id,k] of [['flow-name','name'],['flow-type','type'],['flow-script','script'],['flow-note','note'],['flow-canvas','canvas']]){let e=document.getElementById(id);if(e)f[k]=e.value;}document.querySelectorAll('[data-folder-role]').forEach(e=>f.folderRoles[e.dataset.folderRole]=e.value)}
async function loadFiles(files){let f=state.flow;if(!f)return;let rejected=0;for(let file of files){if(!/image\/(jpeg|png|webp|gif|avif)/.test(file.type)){rejected++;continue}if(file.size>15*1024*1024){toast('单张图片最大支持15MB');continue}let bytes=await file.arrayBuffer(),digest;if(crypto.subtle)digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');else digest=file.name+file.size+file.lastModified;const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});if(state.flow!==f)return;const rel=file.webkitRelativePath||file.name,folder=rel.includes('/')?rel.slice(0,rel.lastIndexOf('/')):'';f.items.push({name:file.name.replace(/\.[^.]+$/,''),url,folder,fingerprint:digest,kind:'',category:'',tags:[],selected:true});if(!f.name&&folder)f.name=folder.split('/')[0];}if(rejected)toast('已跳过不支持的文件，仅接收图片');renderLayers()}
function parseFlow(){const f=state.flow;if(!f.items.some(i=>i.selected))return toast('请先选择至少一张图片');f.step=2;f.parsing=true;f.progress=0;renderLayers();clearInterval(parseTimer);parseTimer=setInterval(()=>{if(state.flow!==f){clearInterval(parseTimer);return}f.progress=Math.min(100,f.progress+20);if(f.progress===100){clearInterval(parseTimer);f.parsing=false;if(!f.name)f.name=f.source==='canvas'?(f.canvas==='c1'?'清透底妆 · 画布导入':'高光时刻 · 画布导入'):'新建导入项目';f.items.filter(i=>i.selected).forEach((i,n)=>{if(f.source==='canvas'&&n===f.items.filter(i=>i.selected).length-1){i.kind='';i.category='';i.tags=[];return}if(!i.kind){let kind=!f.upload&&n===f.items.filter(i=>i.selected).length-1?'':f.upload&&lib(state.page)?state.page:CONFIG.libraries[n%CONFIG.libraries.length].name;i.kind=kind;i.category=lib(kind)?.categories[0]||'';i.tags=lib(kind)?.tags.slice(0,1)||[]}})}renderLayers()},350)}
function saveFlow(){rememberFlow();const f=state.flow,items=f.items.filter(i=>i.selected);if(!f.upload&&!f.target&&!f.name.trim())return toast('请填写项目名称');if(f.script&&safeLink(f.script)==='#')return toast('请输入有效的 http 或 https 脚本链接');if(items.some(i=>!lib(i.kind)||!i.category))return toast('请为每张图片选择图库和二级分类');let p=f.target?getProject():null;if(!f.upload&&!p){p={id:uid(),name:f.name.trim(),type:f.type,creator:'汤莉',created:now(),updated:now(),script:f.script,note:f.note,roles:[],refs:[]};db().projects.unshift(p);f.resultProject=p.id;}if(p){Object.entries(f.folderRoles).forEach(([folder,name])=>{name=name.trim();if(name&&!p.roles.some(r=>r.name===name))p.roles.push({id:uid(),name,description:'',avatar:''})})}let added=0,reused=0;items.forEach(i=>{let a=db().assets.find(a=>a.fingerprint===i.fingerprint);if(a)reused++;else{a={id:uid(),name:i.name||'未命名资产',kind:i.kind,category:i.category,tags:i.tags,url:i.url,fingerprint:i.fingerprint,source:f.source==='canvas'?'星策画布':f.source==='external'?'外部画布上传':'本地上传',created:now(),description:'',prompt:''};db().assets.push(a);added++}if(p){const roleName=(i.roleName||f.folderRoles[i.folder]||'').trim();if(roleName&&!p.roles.some(r=>r.name===roleName))p.roles.push({id:uid(),name:roleName,description:'',avatar:''});const role=p.roles.find(r=>r.name===roleName)?.id||'';if(!p.refs.some(r=>r.asset===a.id&&r.role===role&&r.folder===i.folder))p.refs.push({asset:a.id,role,folder:i.folder});p.updated=now();}f.resultKind=a.kind});f.added=added;f.reused=reused;f.done=true;persist();render()}
function confirmAction(title,message,fn){state.confirm={title,message,fn};renderLayers()}
function closeFront(){if(state.flow&&!state.flow.done&&!state.confirm&&state.flow.items.length){act('close-flow');return}if(state.confirm)state.confirm=null;else if(state.flow){clearInterval(parseTimer);state.flow=null}else if(state.layer){state.layer=null;state.layerValue=null}else state.asset=null;renderLayers()}
function navigateAsset(delta){let current=getAsset(state.asset);let candidates=state.project?[...new Set(getProject().refs.map(r=>r.asset))].map(getAsset).filter(Boolean):lib(state.page)?db().assets.filter(a=>a.kind===state.page&&(state.category==='all'||a.category===state.category)&&(!state.tags.length||state.tags.some(t=>a.tags.includes(t)))):state.page==='search'?db().assets.filter(a=>assetMatches(a,state.search)):db().assets.filter(a=>a.kind===current?.kind);if(!candidates.length)return;let i=candidates.findIndex(a=>a.id===state.asset);state.asset=candidates[(i+delta+candidates.length)%candidates.length].id;renderLayers()}
function act(action,value,el){switch(action){
case 'clear-search':state.search='';const query=document.getElementById('global-query');if(query){query.value='';query.focus()}break;
case 'user-menu':{let menu=document.getElementById('user-dropdown');menu.hidden=!menu.hidden;el.setAttribute('aria-expanded',String(!menu.hidden));break;}
case 'page':state.page=value;state.category='all';state.tags=[];state.filters=false;state.search='';render();break;
case 'mode':mode=value;state.project=null;state.asset=null;state.layer=null;state.flow=null;state.projectType='all';state.category='all';state.tags=[];render();break;
case 'reset':confirmAction('重置演示','将重置当前模式下的本地修改，恢复到初始数据。',()=>{stores[mode]=mode==='demo'?cleanSeed():EMPTY();persist();state.project=null;state.asset=null;render();toast('已重置当前演示')});break;
case 'ptype':state.projectType=value;render();break;case 'category':state.category=value;render();break;case 'filters':state.filters=!state.filters;render();break;case 'tag':state.tags=state.tags.includes(value)?state.tags.filter(t=>t!==value):[...state.tags,value];render();break;case 'clear-filters':state.tags=[];state.category='all';render();break;case 'search-tab':state.searchTab=value;render();break;
case 'project':state.project=value;state.role='all';state.folder='all';state.projectCategory='all';renderLayers();break;
case 'asset':state.asset=value;state.layer=null;renderLayers();break;
case 'close':if(state.flow||state.layer||state.asset)closeFront();else{state.project=null;renderLayers()}break;case 'close-front':closeFront();break;
case 'new-project':state.layer='new';renderLayers();break;case 'edit-project':state.layer='edit-project';renderLayers();break;
case 'create-project':case 'save-project':{let name=document.getElementById('new-name').value.trim(),t=document.getElementById('new-type').value,s=document.getElementById('new-script').value.trim(),note=document.getElementById('new-note').value;if(!name)return toast('请填写项目名称');if(s&&safeLink(s)==='#')return toast('请输入有效的 http 或 https 脚本链接');let p=action==='save-project'?getProject():{id:uid(),creator:'汤莉',created:now(),refs:[],roles:[]};Object.assign(p,{name,type:t,script:s,note,updated:now()});if(action==='create-project')db().projects.unshift(p);state.layer=null;state.project=p.id;state.role='all';state.folder='all';state.projectCategory='all';persist();render();toast(action==='create-project'?'项目已创建':'项目已更新');break}
case 'delete-project':confirmAction('删除项目','仅删除此项目及其引用关系，图库中的原始资产会保留。',()=>{db().projects=db().projects.filter(p=>p.id!==state.project);state.project=null;state.asset=null;persist();render();toast('项目已删除，原始资产已保留')});break;
case 'role':state.role=value;state.folder='all';renderLayers();break;case 'folder':state.folder=value;renderLayers();break;case 'project-category':state.projectCategory=value;renderLayers();break;
case 'edit-script':state.layer='script';renderLayers();break;case 'save-script':{let s=document.getElementById('script-url').value.trim();if(s&&safeLink(s)==='#')return toast('请输入有效的 http 或 https 链接');let p=getProject();p.script=s;p.note=document.getElementById('script-note').value;p.updated=now();state.layer=null;persist();render();toast('脚本信息已保存');break}
case 'new-role':state.layer='role';state.layerValue=null;renderLayers();break;case 'edit-role':state.layer='role';state.layerValue=value;renderLayers();break;
case 'save-role':{let p=getProject(),name=document.getElementById('role-name').value.trim();if(!name)return toast('请填写角色姓名');let r=p.roles.find(r=>r.id===state.layerValue);if(!r){r={id:uid()};p.roles.push(r)}Object.assign(r,{name,description:document.getElementById('role-description').value,avatar:document.getElementById('role-avatar').value});p.updated=now();state.layer=null;state.role=r.id;persist();render();toast('角色已保存');break}
case 'delete-role':confirmAction('删除角色','删除角色后，其资产引用保留在项目的全部资产中。',()=>{let p=getProject();p.roles=p.roles.filter(r=>r.id!==value);p.refs.forEach(r=>{if(r.role===value)r.role=''});p.updated=now();state.role='all';persist();render();toast('角色已删除')});break;
case 'save-asset':{let a=getAsset(state.asset),name=document.getElementById('asset-name').value.trim();if(!name)return toast('请填写资产名称');a.name=name;a.category=document.getElementById('asset-category').value;a.tags=[...document.querySelectorAll('[name=asset-tag]:checked')].map(e=>e.value);a.description=document.getElementById('asset-description').value;persist();render();toast('信息已保存，所有项目引用同步显示');break}
case 'download':{let a=getAsset(state.asset),link=document.createElement('a');link.href=a.url;link.download=a.name+(a.url.endsWith('.svg')?'.svg':a.url.startsWith('data:image/png')?'.png':'.jpg');link.click();toast('已开始下载原始图片');break}
case 'delete-asset':if(countRefs(state.asset))return toast('此资产仍有引用，请先在项目中移出');confirmAction('删除资产','确定删除这张没有引用的资产？',()=>{db().assets=db().assets.filter(a=>a.id!==state.asset);state.asset=null;persist();render();toast('资产已删除')});break;
case 'remove-ref':{let p=getProject(),refs=p.refs.filter(r=>r.asset===value&&(state.role==='all'||r.role===state.role)&&(state.folder==='all'||r.folder===state.folder));confirmAction('移出项目',`解除当前范围内的 ${refs.length} 条引用，图库原图保持不变。`,()=>{p.refs=p.refs.filter(r=>!refs.includes(r));p.updated=now();persist();render();toast('已解除引用')});break}
case 'add-reference':state.layer='reference';renderLayers();break;case 'back-to-asset':state.layer=null;renderLayers();break;
case 'save-reference':{let id=document.getElementById('ref-project')?.value,p=db().projects.find(p=>p.id===id);if(!p)return toast('请先创建项目');let role=document.getElementById('ref-role')?.value||'';if(p.refs.some(r=>r.asset===state.asset&&r.role===role))return toast('该资产已引用到此项目及角色');p.refs.push({asset:state.asset,role,folder:''});p.updated=now();persist();state.layer=null;render();toast('已添加项目引用');break}
case 'open-ref':state.project=value;state.asset=null;state.role='all';state.folder='all';state.projectCategory='all';renderLayers();break;
case 'pick-assets':state.layer='pick';renderLayers();break;case 'save-picked':{let selected=[...document.querySelectorAll('[name=pick-asset]:checked')].map(e=>e.value);if(!selected.length)return toast('请勾选至少一张图片');let p=getProject(),role=document.getElementById('pick-role')?.value||'',added=0;selected.forEach(id=>{if(!p.refs.some(r=>r.asset===id&&r.role===role)){p.refs.push({asset:id,role,folder:''});added++}});p.updated=now();state.layer=null;persist();render();toast(`已新增 ${added} 条引用，已有引用自动跳过`);break}
case 'send-canvas':state.layer='canvas';renderLayers();break;case 'finish-canvas':state.layer=null;renderLayers();toast('演示：已添加到所选画布，未写入真实服务');break;
case 'prev-asset':navigateAsset(-1);break;case 'next-asset':navigateAsset(1);break;
case 'import':startFlow();break;case 'upload':startFlow(true);break;case 'project-upload':startFlow(false,state.project);break;case 'flow-source':rememberFlow();state.flow.source=value;state.flow.items=[];renderLayers();break;
case 'flow-next':rememberFlow();state.flow.step=1;if(state.flow.source==='canvas'&&!state.flow.items.length)state.flow.items=applyConfigOps({assets:structuredClone(SAMPLE_ASSETS),projects:[]}).assets.filter(a=>lib(a.kind)&&lib(a.kind).key!=='品牌LOGO').slice(state.flow.canvas==='c2'?1:0,state.flow.canvas==='c2'?8:7).map(a=>({...a,selected:true,folder:state.flow.canvas==='c2'?(a.kind===(CONFIG.libraries.find(l=>l.key==='人物')?.name||'人物')?'女主':'服化道'):'画布图片'}));renderLayers();break;
case 'choose-files':document.getElementById('files-input').click();break;case 'choose-folder':document.getElementById('folder-input').click();break;case 'flow-select-all':state.flow.items.forEach(i=>i.selected=true);renderLayers();break;case 'flow-select-none':state.flow.items.forEach(i=>i.selected=false);renderLayers();break;
case 'flow-parse':parseFlow();break;case 'flow-back':rememberFlow();state.flow.step=Math.max(0,state.flow.step-1);renderLayers();break;case 'cancel-parse':clearInterval(parseTimer);state.flow.parsing=false;state.flow.step=1;renderLayers();break;
case 'close-flow':rememberFlow();if(state.flow.items.length&&!state.flow.done)confirmAction('取消导入','取消后本次尚未入库的图片不会保存。',()=>{clearInterval(parseTimer);state.flow=null;renderLayers()});else{state.flow=null;renderLayers()}break;
case 'flow-save':saveFlow();break;case 'flow-finish':{let f=state.flow;if(f.target||f.resultProject){state.project=f.target||f.resultProject;state.role='all';state.folder='all';state.projectCategory='all'}else{state.page=f.resultKind;state.category='all';state.tags=[]}state.flow=null;render();break}
case 'cancel-confirm':state.confirm=null;renderLayers();break;case 'confirm-action':{let c=state.confirm;state.confirm=null;c.fn();renderLayers();break}
}}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(t){e.preventDefault();act(t.dataset.action,t.dataset.value,t);return}const tag=e.target.closest('[data-review-tag]');if(tag){rememberFlow();let i=state.flow.items[Number(tag.dataset.index)],v=tag.dataset.reviewTag;i.tags=i.tags.includes(v)?i.tags.filter(t=>t!==v):[...i.tags,v];renderLayers()}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='project-sort'){state.sort=t.value;render()}if(t.id==='new-type'){document.getElementById('new-script-fields').hidden=type(t.value).template!=='roles'}if(t.id==='ref-project'){document.getElementById('ref-role-container').innerHTML=refRoleSelect(db().projects.find(p=>p.id===t.value))}if(t.id==='files-input'||t.id==='folder-input')loadFiles(t.files);if(t.hasAttribute('data-flow-pick')){state.flow.items[Number(t.dataset.flowPick)].selected=t.checked;renderLayers()}if(t.dataset.review){rememberFlow();let i=state.flow.items[Number(t.dataset.index)];i[t.dataset.review]=t.value;if(t.dataset.review==='kind'){i.category=lib(t.value)?.categories[0]||'';i.tags=[];renderLayers()}}if(t.id==='flow-type'){rememberFlow();renderLayers()}});
document.addEventListener('input',e=>{let t=e.target;if(t.dataset.review&&t.dataset.review==='name')state.flow.items[Number(t.dataset.index)].name=t.value});
document.addEventListener('submit',e=>{if(e.target.id==='global-search'){e.preventDefault();state.search=document.getElementById('global-query').value;state.page='search';state.searchTab='all';render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.confirm||state.layer||state.asset||state.flow)closeFront();else if(state.project){state.project=null;renderLayers()}}if(state.asset&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){if(e.key==='ArrowLeft')navigateAsset(-1);if(e.key==='ArrowRight')navigateAsset(1)}if((e.key==='Enter'||e.key===' ')&&e.target.matches('article[data-action]')){e.preventDefault();act(e.target.dataset.action,e.target.dataset.value,e.target)}});
document.addEventListener('dragover',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();e.target.closest('#drop-zone').style.borderColor='#526dff'}});document.addEventListener('drop',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();loadFiles(e.dataTransfer.files)}});
if(!IS_ADMIN)render();
if(typeof window!=='undefined')window.addEventListener('storage',e=>{if(e.key===CONFIG_KEY||e.key?.startsWith('xingce-assets-v1-')){const oldPage=state.page;readConfig();for(const m of ['empty','demo']){try{const raw=localStorage.getItem('xingce-assets-v1-'+m);if(raw)stores[m]=JSON.parse(raw)}catch{}applyConfigOps(stores[m])}for(const op of configJournal)if(op.scope==='library'&&state.page===op.old)state.page=op.name;if(!['projects','search'].includes(state.page)&&!lib(state.page))state.page='projects';state.category='all';state.tags=[];state.layer=null;state.asset=null;if(IS_ADMIN)renderAdmin();else render();}});
document.addEventListener('click',e=>{if(!e.target.closest('.user-menu')){const menu=document.getElementById('user-dropdown');if(menu)menu.hidden=true;}});

let dialogReturnFocus=null,activeDialogKey='';
function enhanceDialogs(){const overlays=[...document.querySelectorAll('.overlay')],top=overlays.at(-1);document.body.classList.toggle('dialog-open',!!top);for(const layer of overlays){layer.inert=layer!==top;layer.setAttribute('aria-hidden',String(layer!==top))}if(!top){if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus();dialogReturnFocus=null;activeDialogKey='';return}const dialog=top.querySelector('[role=dialog]');if(!dialog)return;const key=[state.asset,state.layer,state.project,!!state.confirm,!!state.flow,dialog.getAttribute('aria-label')].join('|');if(key!==activeDialogKey||!dialog.contains(document.activeElement)){if(!dialogReturnFocus)dialogReturnFocus=document.activeElement;activeDialogKey=key;const input=dialog.querySelector('input:not([type=checkbox]):not([type=file]),textarea,select');const target=input||dialog.querySelector('button,a[href]');target?.focus({preventScroll:true})}}
document.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const dialog=[...document.querySelectorAll('.overlay')].at(-1)?.querySelector('[role=dialog]');if(!dialog)return;const items=[...dialog.querySelectorAll('button:not(:disabled),a[href],input:not([hidden]),select,textarea,[tabindex="0"]')].filter(x=>x.getClientRects().length&&!x.closest('[hidden]'));if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){e.preventDefault();first.focus()}});
